export function AgentWorkspace({
  task = "{{task}}",
  currentStep = "{{currentStep}}",
  stepIndex = {{stepIndex}},
  accent = "{{accent}}",
}) {
  const pct = (stepIndex / 5) * 100;
  return (
    <section style={{ fontFamily: "system-ui, sans-serif", fontSize: 14, lineHeight: 1.5, color: "#241430",
      background: "#FAF7F2", maxWidth: 360, padding: 18, borderRadius: 14, border: "1px solid #24143014", boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 4px", fontSize: 11, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".05em", color: "#24143099" }}>Agent workspace</p>
      <h3 style={{ margin: "0 0 10px", fontSize: 17, fontWeight: 600 }}>{task}</h3>
      <p style={{ margin: "0 0 10px", fontSize: 13, color: "#24143099" }}>Step {stepIndex} of 5 — {currentStep}</p>
      <div role="progressbar" aria-valuemin={0} aria-valuemax={5} aria-valuenow={stepIndex} aria-label="Task progress"
        style={{ height: 8, borderRadius: 999, background: "#24143014", overflow: "hidden" }}>
        <div className="aw-bar" style={{ height: "100%", borderRadius: 999, background: accent, width: `${pct}%` }} />
      </div>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .aw-bar { transition: width .2s ease; }
        }
      `}</style>
    </section>
  );
}
